const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 3 10 5-10 5L2 8l10-5zM2 12l10 5 10-5M2 16l10 5 10-5"/></svg>`;
const stamp=v=>v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'尚无记录';
const scalar=v=>v===undefined||v===null?'未声明':typeof v==='object'?JSON.stringify(v):String(v);
const safe=v=>{if(typeof v!=='string'||!v.trim())return'';try{const u=new URL(v,location.origin);if(!['http:','https:'].includes(u.protocol)||[...u.searchParams.keys()].some(k=>/^(tk|sig|token|api_key|access_token|se|sp|sv)$/i.test(k)))return'';return u.href}catch{return''}};
const stages=o=>({catalogued:o.stages?.catalogued??true,pixel_verified:o.stages?.pixel_verified??o.pixel_verified??false,analysis_ready:o.stages?.analysis_ready??o.analysis_ready??false});
const bands=a=>{const list=a.bands||a.eo_bands||a['eo:bands']||[];return Array.isArray(list)?list.map(b=>typeof b==='string'?b:b.common_name||b.name||b.id||'').filter(Boolean).join(' / '):scalar(list)};
const unitText=v=>({reflectance_after_calibration:'定标后反射率',surface_reflectance:'地表反射率',reflectance:'反射率',unitless:'无量纲',dimensionless:'无量纲',dn:'数字量化值 DN','1':'无量纲'}[v]||scalar(v));
const physical=(a,key)=>a[key]??a.raster_bands?.[0]?.[key]??a['raster:bands']?.[0]?.[key]??(typeof a.bands?.[0]==='object'?a.bands[0][key]:undefined);
export class ObservationLibrary{
 constructor({api,toast,showDialog,onPrepareAnalysis,onMap,sources=[]}){this.api=api;this.toast=toast;this.showDialog=showDialog;this.onPrepareAnalysis=onPrepareAnalysis;this.onMap=onMap;this.sources=sources;this.element=document.createElement('div');this.element.className='ol-library';this.filters={source_id:'',collection:'',start:'',end:'',cloud_max:'',q:''};this.items=[];this.total=0;this.limit=20;this.offset=0;this.stats={};this.loading=false;this.ready=false;this.error='';this.sequence=0;this.matches={};this.bind()}
 bind(){this.element.addEventListener('input',e=>{const key=e.target.dataset.observationFilter;if(key)this.filters[key]=e.target.value});this.element.addEventListener('change',e=>{const key=e.target.dataset.observationFilter;if(key)this.filters[key]=e.target.value});this.element.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('input')){e.preventDefault();this.offset=0;this.load()}});this.element.addEventListener('click',async e=>{const b=e.target.closest('[data-ol-action]');if(!b||b.disabled)return;try{b.disabled=true;await this.act(b.dataset.olAction,b)}catch(error){this.toast(error.message)}finally{if(b.isConnected)b.disabled=false}});document.addEventListener('click',async e=>{const b=e.target.closest('#dialog [data-ol-action]');if(!b||b.disabled)return;try{b.disabled=true;await this.act(b.dataset.olAction,b)}catch(error){this.toast(error.message)}finally{if(b.isConnected)b.disabled=false}})}
 mount(host){host.replaceChildren(this.element);this.render();if(!this.loading)this.load()}
 async load(){if(this.filters.start&&this.filters.end&&this.filters.start>this.filters.end){this.error='开始日期不能晚于结束日期';this.render();return}if(this.filters.cloud_max!==''&&(!Number.isFinite(Number(this.filters.cloud_max))||Number(this.filters.cloud_max)<0||Number(this.filters.cloud_max)>100)){this.error='景云量上限须为0至100';this.render();return}const sequence=++this.sequence;this.loading=true;this.error='';this.render();try{const query=new URLSearchParams({limit:String(this.limit),offset:String(this.offset)});for(const[k,v]of Object.entries(this.filters))if(v!=='')query.set(k,v);const result=await this.api('/observations?'+query);if(sequence!==this.sequence)return;this.items=Array.isArray(result.items)?result.items:[];this.total=Number(result.total)||0;this.stats=result.stats||{};this.ready=true}catch(error){if(sequence===this.sequence)this.error=error.message}finally{if(sequence===this.sequence){this.loading=false;this.render()}}}
 sourceName(o){return this.sources.find(s=>s.id===o.source_id)?.name||o.source_id||'来源待说明'}
 render(){const stateCount=(...keys)=>{for(const k of keys)if(Number.isFinite(this.stats[k]))return this.stats[k];return'—'};const eligible=this.sources.filter(s=>s.stages?.catalog_searchable),sourceOptions=eligible.map(s=>`<option value="${esc(s.id)}" ${this.filters.source_id===s.id?'selected':''}>${esc(s.provider)} · ${esc(s.name)}</option>`).join('');this.element.innerHTML=`<section class="ol-heading"><div><span>OBSERVATIONS & ASSETS</span><h2>影像资源库</h2><p>保存真实检索到的观测及资产版本，按来源、时相和波段条件选择数据。</p></div><button data-ol-action="refresh">刷新资源</button></section><div class="ol-stats"><div><b>${this.ready?this.total:'—'}</b><span>符合条件的资源版本</span></div><div><b>${stateCount('assets','asset_count','total_assets')}</b><span>全库资产元数据</span></div><div><b>${stateCount('pixel_verified','pixel_verified_count')}</b><span>全库像元读取证据</span></div><p>入库保存目录与资产元数据；<br>实际像元仍由分析任务按需读取。</p></div><form class="ol-filters" onsubmit="return false"><label class="ol-wide">提供方 / 数据集合<select data-observation-filter="source_id"><option value="">全部来源</option>${sourceOptions}</select></label><label>集合标识<input data-observation-filter="collection" value="${esc(this.filters.collection)}" placeholder="如 landsat-c2-l2"></label><label>观测开始<input type="date" data-observation-filter="start" value="${esc(this.filters.start)}"></label><label>观测结束<input type="date" data-observation-filter="end" value="${esc(this.filters.end)}"></label><label>景云量上限 %<input type="number" min="0" max="100" step="any" data-observation-filter="cloud_max" value="${esc(this.filters.cloud_max)}" placeholder="不限"></label><label class="ol-query">搜索记录<input data-observation-filter="q" value="${esc(this.filters.q)}" placeholder="观测名称、平台或来源…"></label><div class="ol-filter-actions"><button class="primary" data-ol-action="filter" ${this.loading?'disabled':''}>筛选资源</button><button data-ol-action="reset" ${this.loading?'disabled':''}>重置</button></div></form>${this.error?`<div class="ol-error" role="alert"><b>资源库暂未读取</b><p>${esc(this.error)}</p><button data-ol-action="refresh">重新读取</button></div>`:''}${this.loading?'<div class="ol-empty"><span class="mc-spinner"></span><h3>正在读取已入库资源…</h3></div>':this.items.length?`<div class="ol-results-summary"><span>${this.offset+1}–${Math.min(this.offset+this.items.length,this.total)} / ${this.total} 条资源版本</span><small>同景跨源可能重复；景云量不是选区有效覆盖率。</small></div><div class="ol-rows">${this.items.map(o=>this.row(o)).join('')}</div><div class="ol-pagination"><button data-ol-action="previous" ${this.offset<=0?'disabled':''}>上一页</button><span>第 ${Math.floor(this.offset/this.limit)+1} 页</span><button data-ol-action="next" ${this.offset+this.items.length>=this.total?'disabled':''}>下一页</button></div>`:!this.error?`<div class="ol-empty">${icon}<h3>${this.ready&&this.total===0?'当前条件下没有观测记录':'资源尚未载入'}</h3><p>在“目录检索”中查询实际影像，并将命中记录入库。<br>入库后可继续查看波段、匹配算法并准备分析。</p><button data-ol-action="discover">前往目录检索</button></div>`:''}`}
 row(o){const s=stages(o),assets=Array.isArray(o.assets)?o.assets:[],date=o.datetime||o.acquired_at,title=o.item_id||o.name||o.id;return `<article class="ol-row"><div class="ol-row-icon">${icon}</div><div class="ol-row-main"><div><b>${esc(this.sourceName(o))}</b><time>${esc(date?.slice(0,10)||'日期未声明')}</time></div><h3>${esc(title)}</h3><p>${esc(o.provider||'提供方见详情')} · ${esc(Array.isArray(o.platform)?o.platform.join(' / '):o.platform||'平台未声明')} · ${assets.length} 项资产 · ${typeof o.cloud_cover==='number'?'景云量 '+o.cloud_cover.toFixed(1)+'%':'云量不适用 / 未声明'}</p><div class="ol-stage-tags"><span>目录已入库</span><span class="${s.pixel_verified?'positive':''}">${s.pixel_verified?'有像元读取证据':'像元尚未核查'}</span><span class="${s.analysis_ready?'positive':''}">${s.analysis_ready?'存在匹配分析适配':'分析适配待匹配'}</span></div></div><div class="ol-row-actions"><button data-ol-action="detail" data-id="${esc(o.id)}">资源详情</button><button data-ol-action="prepare" data-id="${esc(o.id)}">匹配分析</button></div></article>`}
 async detail(id){const o=await this.api('/observations/'+encodeURIComponent(id));this.detailObservation=o;const assets=Array.isArray(o.assets)?o.assets:[],s=stages(o);this.showDialog('观测与波段资产',`<div class="ol-detail-head"><span>${esc(this.sourceName(o))}</span><h3>${esc(o.item_id||o.name||o.id)}</h3><p>${esc(o.provider||'提供方见来源')} · ${esc(o.datetime||'观测时间未声明')}</p></div><div class="ol-detail-facts">${[['集合',o.collection],['平台',Array.isArray(o.platform)?o.platform.join(' / '):o.platform],['景云量',typeof o.cloud_cover==='number'?o.cloud_cover+'%':'不适用 / 未声明'],['范围',Array.isArray(o.bbox)?o.bbox.map(n=>Number(n).toFixed(5)).join(', '):'未声明'],['入库时间',stamp(o.ingested_at||o.created_at)],['最近目录发现',stamp(o.last_seen_at||o.updated_at)],['像元读取',s.pixel_verified?'仅已验证窗口有读取证据':'尚无像元读取证据']].map(([k,v])=>`<div><span>${k}</span><b>${esc(scalar(v))}</b></div>`).join('')}</div><h3 class="ol-detail-title">波段、定标与质量资产</h3><div class="ol-asset-scroll"><table class="ol-asset-table"><thead><tr><th>资产 / 语义</th><th>分辨率</th><th>比例 / 偏移</th><th>单位 / 无效值</th></tr></thead><tbody>${assets.map(a=>`<tr><td><b>${esc(a.key||a.id||a.name||'未命名')}</b><small>${esc(bands(a)||a.common_name||a.title||(a.roles||[]).join(' / ')||'语义未声明')}</small></td><td>${esc(scalar(a.resolution??a.gsd??a.spatial_resolution))}</td><td>${esc(scalar(physical(a,'scale')))}<br>${esc(scalar(physical(a,'offset')))}</td><td>${esc(unitText(physical(a,'unit')))}<br>nodata ${esc(scalar(physical(a,'nodata')))}</td></tr>`).join('')||'<tr><td colspan="4">该记录尚未提供可展示的波段资产元数据。</td></tr>'}</tbody></table></div><p class="ol-detail-note">比例、偏移、单位与质量资产按提供方声明保存；缺失不填为默认值。目录入库不等于像元已下载，具体波段和质量掩膜由执行任务再次核验。</p><details class="sw-technical"><summary>版本、来源与资产记录</summary><pre>${esc(JSON.stringify({id:o.id,source_id:o.source_id,collection:o.collection,stages:o.stages,pixel_uses:o.pixel_uses,metadata_sha256:o.metadata_sha256,provenance:o.provenance,assets},null,2))}</pre></details><div class="ol-detail-actions"><button data-ol-action="prepare" data-id="${esc(o.id)}">查看可匹配的分析</button>${Array.isArray(o.bbox)?`<button data-ol-action="map" data-id="${esc(o.id)}">定位观测范围</button>`:''}${safe(o.source_href||o.provenance?.source_url)?`<a href="${esc(safe(o.source_href||o.provenance?.source_url))}" target="_blank" rel="noopener noreferrer">提供方来源 ↗</a>`:''}</div>`)}
 async prepare(id){const o=this.detailObservation?.id===id?this.detailObservation:await this.api('/observations/'+encodeURIComponent(id));const response=await this.api('/algorithm-matches',{method:'POST',body:{observation_id:id}});this.matchObservation=o;this.matchResponse=response;const raw=Array.isArray(response.matches)?response.matches:Array.isArray(response.algorithms)?response.algorithms:[];this.matchItems=raw;this.showDialog('选择匹配的分析',`<div class="ol-detail-head"><span>${esc(this.sourceName(o))}</span><h3>${esc(o.item_id||o.name||o.id)}</h3><p>观测日期 ${esc(o.datetime?.slice(0,10)||'未声明')}；匹配只检查当前适配条件，不代表已经执行或质量合格。</p></div><div class="ol-match-list">${raw.map((m,i)=>{const ok=m.ready===true;return `<article class="${ok?'ready':''}"><div><b>${esc(m.name||m.label||m.id||m.index_id||'分析工具')}</b><span>${ok?'可以准备条件':'尚不能执行'}</span></div><p>${esc([...(m.reasons||[]),...(m.gaps||[]),...(m.limitations||[])].map(x=>typeof x==='string'?x:x.message||scalar(x)).join('；')||m.message||'条件说明见契约')}</p>${ok?`<button data-ol-action="use-match" data-index="${i}">准备分析条件</button>`:''}</article>`}).join('')||'<div class="ol-empty"><h3>当前没有可执行的匹配</h3><p>该资源仍可用于目录发现，需补齐对应的像元读取与算法适配。</p></div>'}</div><p class="ol-detail-note">选择后将绑定此条指定观测并填写来源、日期与指数。请在地图上选择其覆盖内的小分析区域，不直接用整景包络运行。执行质量由任务再次核验；此操作不会自动开始计算。</p>`)}
 async useMatch(index){const m=this.matchItems?.[index],o=this.matchObservation;if(!m||!o)return;await this.onPrepareAnalysis?.({observation:o,match:m})}
 async act(action,b){if(action==='refresh'){await this.load()}else if(action==='filter'){this.offset=0;await this.load()}else if(action==='reset'){this.filters={source_id:'',collection:'',start:'',end:'',cloud_max:'',q:''};this.offset=0;await this.load()}else if(action==='previous'){this.offset=Math.max(0,this.offset-this.limit);await this.load()}else if(action==='next'){this.offset+=this.limit;await this.load()}else if(action==='detail')await this.detail(b.dataset.id);else if(action==='prepare')await this.prepare(b.dataset.id);else if(action==='map'){const o=this.detailObservation?.id===b.dataset.id?this.detailObservation:await this.api('/observations/'+encodeURIComponent(b.dataset.id));await this.onMap?.(o)}else if(action==='use-match')await this.useMatch(Number(b.dataset.index));else if(action==='discover')this.onDiscover?.()}
}
